function f(t){return(t??60)===30?30:60}function e(t){const n=Math.floor(t/60),r=t%60,o=n<12?"AM":"PM";return`${n%12===0?12:n%12}:${String(r).padStart(2,"0")} ${o}`}function s(t,n){return`${e(t)} – ${e(n)}`}function i(t){return t.start_minute!=null?t.start_minute:t.start_hour>24?t.start_hour:t.start_hour*60}function a(t){return t.end_minute!=null?t.end_minute:t.end_hour>24?t.end_hour:t.end_hour*60}function c(t,n){const r=[...t].sort((o,u)=>o-u);return r.every((o,u)=>u===0||o===r[u-1]+n)}function l(t,n,r){return Math.round(t*n*(r/60))}function h(t,n){return t*n/60}function m(t){return s(i(t),a(t))}function d(t){return e(i(t))}export{d as a,e as b,l as c,f as d,m as f,c as i,h as s};
